import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

/** Opening hours: windows such as `mon-fri@08:00-18:00,sat@10:00-14:00` and the test whether a minute of the week lies in them. */
final class Hours {
    static final String[] DAYS = {"mon", "tue", "wed", "thu", "fri", "sat", "sun"};

    private Hours() {}

    static final class Window {
        final Set<Integer> days;
        final int start;
        final int end;
        final boolean crossing;

        Window(Set<Integer> days, int start, int end) {
            this.days = days;
            this.start = start;
            this.end = end;
            this.crossing = end < start;
        }
    }

    static int dayIndex(String text) {
        for (int i = 0; i < DAYS.length; i++) {
            if (DAYS[i].equals(text)) {
                return i;
            }
        }
        return -1;
    }

    /** Minutes since midnight of `HH:MM`, or -1; `24:00` is accepted only for the end of a window. */
    static int clock(String text, boolean allow24) {
        if (allow24 && text.equals("24:00")) {
            return 1440;
        }
        if (text.length() != 5 || text.charAt(2) != ':') {
            return -1;
        }
        for (int i : new int[] {0, 1, 3, 4}) {
            if (text.charAt(i) < '0' || text.charAt(i) > '9') {
                return -1;
            }
        }
        int h = Integer.parseInt(text.substring(0, 2));
        int m = Integer.parseInt(text.substring(3));
        return h > 23 || m > 59 ? -1 : h * 60 + m;
    }

    /** The weekday numbers (0 = mon) of `*`, `DAY` or `DAY-DAY` (a range may wrap around the end of the week), or null. */
    static Set<Integer> parseDays(String text) {
        Set<Integer> out = new HashSet<>();
        if (text.equals("*")) {
            for (int i = 0; i < 7; i++) {
                out.add(i);
            }
            return out;
        }
        String[] parts = text.split("-", -1);
        if (parts.length == 1 && dayIndex(parts[0]) >= 0) {
            out.add(dayIndex(parts[0]));
            return out;
        }
        if (parts.length == 2 && dayIndex(parts[0]) >= 0 && dayIndex(parts[1]) >= 0) {
            int a = dayIndex(parts[0]);
            int b = dayIndex(parts[1]);
            out.add(a);
            while (a != b) {
                a = (a + 1) % 7;
                out.add(a);
            }
            return out;
        }
        return null;
    }

    /** The windows of a specification, or null when it is bad. */
    static List<Window> parse(String spec) {
        List<Window> windows = new ArrayList<>();
        for (String part : spec.split(",", -1)) {
            String[] halves = part.split("@", -1);
            if (halves.length != 2) {
                return null;
            }
            Set<Integer> days = parseDays(halves[0]);
            String[] span = halves[1].split("-", -1);
            if (days == null || span.length != 2) {
                return null;
            }
            int start = clock(span[0], false);
            int end = clock(span[1], true);
            if (start < 0 || end < 0 || start == end || (end < start && !Config.CROSS)) {
                return null;
            }
            windows.add(new Window(days, start, end));
        }
        return windows;
    }

    /** Whether minute `t` (since Monday 00:00 of week 0) is inside one of the windows; no windows at all (null) means always open. */
    static boolean isOpen(List<Window> windows, int t) {
        if (windows == null) {
            return true;
        }
        int day = (t / 1440) % 7;
        int tod = t % 1440;
        for (Window w : windows) {
            if (!w.crossing) {
                if (w.days.contains(day) && w.start <= tod && tod < w.end) {
                    return true;
                }
            } else if ((w.days.contains(day) && tod >= w.start) || (w.days.contains((day + 6) % 7) && tod < w.end)) {
                return true;
            }
        }
        return false;
    }
}

solution.src/Main.java:
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/** turnstile: a scripted door-access controller. */
public class Main {
    static final class Bad extends Exception {
        Bad(String message) {
            super(message);
        }
    }

    private final Venue v = new Venue();
    private final List<String> out = new ArrayList<>();
    private int errors = 0;

    private static boolean isName(String s) {
        if (s.isEmpty() || s.length() > 12 || s.charAt(0) < 'a' || s.charAt(0) > 'z') {
            return false;
        }
        for (char c : s.toCharArray()) {
            if (!((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '-')) {
                return false;
            }
        }
        return true;
    }

    /** `0` or digits without a leading zero, at most five of them. */
    private static boolean isNumber(String s) {
        if (s.isEmpty() || s.length() > 5 || (s.length() > 1 && s.charAt(0) == '0')) {
            return false;
        }
        for (char c : s.toCharArray()) {
            if (c < '0' || c > '9') {
                return false;
            }
        }
        return true;
    }

    private static int number(String text, int lo, int hi, String what) throws Bad {
        if (!isNumber(text) || Integer.parseInt(text) < lo || Integer.parseInt(text) > hi) {
            throw new Bad("bad " + what + " '" + text + "'");
        }
        return Integer.parseInt(text);
    }

    private static String name(String text) throws Bad {
        if (!isName(text)) {
            throw new Bad("bad name '" + text + "'");
        }
        return text;
    }

    private void zone(String[] a) throws Bad {
        Bad usage = new Bad("usage: zone NAME [level N] [cap N] [hours SPEC]");
        if (a.length == 0 || a.length % 2 == 0) {
            throw usage;
        }
        Map<String, String> opts = new HashMap<>();
        for (int i = 1; i < a.length; i += 2) {
            if (!(a[i].equals("level") || a[i].equals("cap") || a[i].equals("hours")) || opts.containsKey(a[i])) {
                throw usage;
            }
            opts.put(a[i], a[i + 1]);
        }
        String id = name(a[0]);
        if (id.equals(Venue.OUTSIDE)) {
            throw new Bad("'outside' is reserved");
        }
        if (v.zones.containsKey(id)) {
            throw new Bad("zone '" + id + "' exists");
        }
        int level = 0;
        int cap = 0;
        List<Hours.Window> windows = null;
        for (int i = 1; i < a.length; i += 2) {
            String val = opts.get(a[i]);
            if (a[i].equals("level")) {
                level = number(val, 0, 9, "level");
            } else if (a[i].equals("cap")) {
                cap = number(val, 1, 99, "cap");
            } else {
                windows = Hours.parse(val);
                if (windows == null) {
                    throw new Bad("bad hours '" + val + "'");
                }
            }
        }
        v.zones.put(id, new Venue.Zone(id, level, cap, windows));
    }

    private void door(String[] a) throws Bad {
        if (a.length != 3) {
            throw new Bad("usage: door ID A B");
        }
        String id = name(a[0]);
        if (v.doors.containsKey(id)) {
            throw new Bad("door '" + id + "' exists");
        }
        for (int i = 1; i < 3; i++) {
            if (!a[i].equals(Venue.OUTSIDE) && !v.zones.containsKey(a[i])) {
                throw new Bad("unknown zone '" + a[i] + "'");
            }
        }
        if (a[2].equals(Venue.OUTSIDE)) {
            throw new Bad("'outside' can only be the outer side");
        }
        if (a[1].equals(a[2])) {
            throw new Bad("door '" + id + "' joins a zone to itself");
        }
        v.doors.put(id, new Venue.Door(id, a[1], a[2]));
    }

    private void badge(String[] a) throws Bad {
        Bad usage = new Bad("usage: badge ID level N [expires in MINUTES]");
        if ((a.length != 3 && a.length != 6) || !a[1].equals("level") || (a.length == 6 && !(a[3].equals("expires") && a[4].equals("in")))) {
            throw usage;
        }
        String id = name(a[0]);
        if (v.badges.containsKey(id)) {
            throw new Bad("badge '" + id + "' exists");
        }
        int level = number(a[2], 0, 9, "level");
        Integer expires = null;
        if (a.length == 6) {
            expires = v.now + number(a[5], 1, 99999, "expiry");
        }
        v.badges.put(id, new Venue.Badge(id, level, expires));
    }

    private void at(String[] a) throws Bad {
        int t;
        if (a.length == 1 && a[0].startsWith("+")) {
            String n = a[0].substring(1);
            if (!isNumber(n) || Integer.parseInt(n) < 1 || Integer.parseInt(n) > 10080) {
                throw new Bad("bad time '" + a[0] + "'");
            }
            t = v.now + Integer.parseInt(n);
        } else if (a.length == 2) {
            int day = Hours.dayIndex(a[0]);
            if (day < 0) {
                throw new Bad("bad day '" + a[0] + "'");
            }
            int tod = Hours.clock(a[1], false);
            if (tod < 0) {
                throw new Bad("bad time '" + a[1] + "'");
            }
            t = v.nextAt(day, tod);
        } else {
            throw new Bad("usage: at DAY HH:MM | at +MINUTES");
        }
        v.setClock(t, out);
    }

    private void lockdown(String[] a) throws Bad {
        if (a.length != 2 || !(a[1].equals("on") || a[1].equals("off"))) {
            throw new Bad("usage: lockdown ZONE on|off");
        }
        if (!v.zones.containsKey(a[0])) {
            throw new Bad("unknown zone '" + a[0] + "'");
        }
        v.zones.get(a[0]).locked = a[1].equals("on");
        out.add("[" + Venue.stamp(v.now) + "] lockdown " + a[0] + " " + a[1]);
    }

    private void swipe(String[] a) throws Bad {
        String form = "usage: swipe BADGE DOOR in|out" + (Config.ESCORT ? " [with BADGE]" : "");
        if ((a.length != 3 && a.length != 5) || !(a[2].equals("in") || a[2].equals("out"))) {
            throw new Bad(form);
        }
        if (a.length == 5 && !(Config.ESCORT && a[2].equals("in") && a[3].equals("with"))) {
            throw new Bad(form);
        }
        if (!v.badges.containsKey(a[0])) {
            throw new Bad("unknown badge '" + a[0] + "'");
        }
        if (!v.doors.containsKey(a[1])) {
            throw new Bad("unknown door '" + a[1] + "'");
        }
        Venue.Badge escort = null;
        if (a.length == 5) {
            if (!v.badges.containsKey(a[4])) {
                throw new Bad("unknown badge '" + a[4] + "'");
            }
            if (a[4].equals(a[0])) {
                throw new Bad("an escort must be another badge");
            }
            escort = v.badges.get(a[4]);
        }
        out.add(v.swipe(v.badges.get(a[0]), v.doors.get(a[1]), a[2], escort));
    }

    private void where(String[] a) throws Bad {
        if (a.length != 1) {
            throw new Bad("usage: where BADGE");
        }
        if (!v.badges.containsKey(a[0])) {
            throw new Bad("unknown badge '" + a[0] + "'");
        }
        Venue.Badge b = v.badges.get(a[0]);
        out.add(b.id + ": " + b.loc + (b.since == null ? "" : " since " + Venue.stamp(b.since)));
    }

    private void who(String[] a) throws Bad {
        if (a.length != 1) {
            throw new Bad("usage: who ZONE");
        }
        String z = a[0];
        if (!z.equals(Venue.OUTSIDE) && !v.zones.containsKey(z)) {
            throw new Bad("unknown zone '" + z + "'");
        }
        List<String> ids = v.occupants(z);
        String count = z.equals(Venue.OUTSIDE) ? ids.size() + "/-" : v.countText(z);
        out.add(z + " (" + count + "): " + (ids.isEmpty() ? "-" : String.join(" ", ids)));
    }

    private void report(String[] a) throws Bad {
        if (a.length != 0) {
            throw new Bad("usage: report");
        }
        for (Venue.Zone z : v.zones.values()) {
            out.add(z.name + ": " + v.countText(z.name) + " level " + z.level + " " + (Hours.isOpen(z.windows, v.now) ? "open" : "closed") + (z.locked ? " lockdown" : ""));
        }
    }

    private void stats(String[] a) throws Bad {
        if (a.length != 0) {
            throw new Bad("usage: stats");
        }
        out.add("grants=" + v.grants + " denies=" + v.denies + " timeouts=" + v.timeouts);
        for (String reason : Config.ORDER) {
            if (v.reasons.getOrDefault(reason, 0) > 0) {
                out.add("deny " + reason + " " + v.reasons.get(reason));
            }
        }
    }

    private void run(String line) {
        String trimmed = line.trim();
        if (trimmed.isEmpty() || trimmed.startsWith("#")) {
            return;
        }
        String[] words = trimmed.split("\\s+");
        String[] args = new String[words.length - 1];
        System.arraycopy(words, 1, args, 0, args.length);
        try {
            switch (words[0]) {
                case "zone": zone(args); break;
                case "door": door(args); break;
                case "badge": badge(args); break;
                case "at": at(args); break;
                case "swipe": swipe(args); break;
                case "lockdown": lockdown(args); break;
                case "where": where(args); break;
                case "who": who(args); break;
                case "report": report(args); break;
                case "stats": stats(args); break;
                default: throw new Bad("unknown command '" + words[0] + "'");
            }
        } catch (Bad e) {
            out.add("error: " + e.getMessage());
            errors++;
        }
    }

    private static String readAll(InputStream in) throws IOException {
        ByteArrayOutputStream buf = new ByteArrayOutputStream();
        byte[] chunk = new byte[8192];
        int n;
        while ((n = in.read(chunk)) > 0) {
            buf.write(chunk, 0, n);
        }
        return new String(buf.toByteArray(), StandardCharsets.UTF_8);
    }

    public static void main(String[] args) throws IOException {
        Main script = new Main();
        for (String line : readAll(System.in).split("\n", -1)) {
            script.run(line);
        }
        StringBuilder sb = new StringBuilder();
        for (String l : script.out) {
            sb.append(l).append('\n');
        }
        System.out.print(sb);
        System.out.flush();
        System.exit(script.errors > 0 ? 1 : 0);
    }
}

solution.src/Venue.java:
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

/** The venue: zones, doors, badges, the clock, and the decision for one swipe. */
final class Venue {
    static final String OUTSIDE = "outside";
    static final int WEEK = 10080;

    static final class Zone {
        final String name;
        final int level;
        final int cap; // 0: unlimited
        final List<Hours.Window> windows;
        boolean locked = false;

        Zone(String name, int level, int cap, List<Hours.Window> windows) {
            this.name = name;
            this.level = level;
            this.cap = cap;
            this.windows = windows;
        }
    }

    static final class Door {
        final String id;
        final String outer;
        final String inner;

        Door(String id, String outer, String inner) {
            this.id = id;
            this.outer = outer;
            this.inner = inner;
        }
    }

    static final class Badge {
        final String id;
        final int level;
        final Integer expires; // absolute minute, or null
        String loc = OUTSIDE;
        Integer since = null; // minute of the last grant or timeout

        Badge(String id, int level, Integer expires) {
            this.id = id;
            this.level = level;
            this.expires = expires;
        }
    }

    final Map<String, Zone> zones = new LinkedHashMap<>();
    final Map<String, Door> doors = new LinkedHashMap<>();
    final Map<String, Badge> badges = new TreeMap<>(); // sorted by id
    int now = 0;
    int grants = 0;
    int denies = 0;
    int timeouts = 0;
    final Map<String, Integer> reasons = new LinkedHashMap<>();

    static String stamp(int t) {
        return String.format("%s %02d:%02d", Hours.DAYS[(t / 1440) % 7], t % 1440 / 60, t % 60);
    }

    List<String> occupants(String zone) {
        List<String> ids = new ArrayList<>();
        for (Badge b : badges.values()) {
            if (b.loc.equals(zone)) {
                ids.add(b.id);
            }
        }
        return ids;
    }

    String countText(String zone) {
        Zone z = zones.get(zone);
        return occupants(zone).size() + "/" + (z.cap > 0 ? String.valueOf(z.cap) : "-");
    }

    /** Moves the clock to `t` and times out the badges that have been inside for too long. */
    void setClock(int t, List<String> out) {
        int before = now;
        now = t;
        if (Config.EVICT > 0 && t > before) {
            for (Badge b : badges.values()) {
                if (!b.loc.equals(OUTSIDE) && t - b.since >= Config.EVICT) {
                    out.add("[" + stamp(t) + "] TIMEOUT " + b.id + " left " + b.loc);
                    b.loc = OUTSIDE;
                    b.since = t;
                    timeouts++;
                }
            }
        }
    }

    /** The first minute at or after now that is weekday `day` at `tod`. */
    int nextAt(int day, int tod) {
        int t = now / WEEK * WEEK + day * 1440 + tod;
        return t >= now ? t : t + WEEK;
    }

    private boolean passback(Badge m, Door door, boolean inward) {
        if (Config.APB.equals("off")) {
            return false;
        }
        String here = inward ? door.outer : door.inner;
        String there = inward ? door.inner : door.outer;
        if (Config.APB.equals("soft")) {
            return m.loc.equals(there);
        }
        return !m.loc.equals(here);
    }

    private boolean fails(String reason, List<Badge> members, Door door, boolean inward) {
        Zone zone = zones.get(door.inner);
        switch (reason) {
            case "expired":
                if (!inward && !Config.EXP_OUT) {
                    return false;
                }
                for (Badge m : members) {
                    if (m.expires != null && now >= m.expires) {
                        return true;
                    }
                }
                return false;
            case "lockdown":
                return (inward || Config.SEAL) && zone.locked;
            case "passback":
                for (Badge m : members) {
                    if (passback(m, door, inward)) {
                        return true;
                    }
                }
                return false;
            case "level":
                int best = 0;
                for (Badge m : members) {
                    best = Math.max(best, m.level);
                }
                return inward && best < zone.level;
            case "hours":
                return inward && !Hours.isOpen(zone.windows, now);
            case "full":
                if (!inward || zone.cap == 0) {
                    return false;
                }
                int movers = 0;
                for (Badge m : members) {
                    if (!m.loc.equals(zone.name)) {
                        movers++;
                    }
                }
                return occupants(zone.name).size() + movers > zone.cap;
            default:
                throw new IllegalStateException(reason);
        }
    }

    /** One swipe; returns the line to print. */
    String swipe(Badge badge, Door door, String direction, Badge escort) {
        List<Badge> members = new ArrayList<>();
        members.add(badge);
        if (escort != null) {
            members.add(escort);
        }
        boolean inward = direction.equals("in");
        String target = inward ? door.inner : door.outer;
        StringBuilder who = new StringBuilder();
        for (Badge m : members) {
            who.append(who.length() > 0 ? "+" : "").append(m.id);
        }
        for (String reason : Config.ORDER) {
            if (fails(reason, members, door, inward)) {
                denies++;
                reasons.merge(reason, 1, Integer::sum);
                return "[" + stamp(now) + "] DENY " + who + " " + door.id + " " + direction + ": " + reason;
            }
        }
        for (Badge m : members) {
            m.loc = target;
            m.since = now;
        }
        grants++;
        String where = target.equals(OUTSIDE) ? "outside" : target + " (" + countText(target) + ")";
        return "[" + stamp(now) + "] GRANT " + who + " " + door.id + " " + direction + " -> " + where;
    }
}

