#!/usr/bin/env python3
"""Example checks: python3 tests/run_examples.py [-v] [group-or-name-fragment]  (builds the program first)"""
import concurrent.futures as cf
import json
import os
import re
import subprocess
import sys
import tempfile

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
CASES = os.path.join(ROOT, "tests", "examples.json")
BUILD = "rm -rf build && mkdir -p build && javac -d build $(find src -name '*.java')"
RUN = [(ROOT + "/" + p[2:]) if p.startswith("@/") else p for p in ["java", "-cp", "@/build", "Main"]]
TIMEOUT = 30
WORKERS = 3


def build():
    if not BUILD:
        return True
    r = subprocess.run(["bash", "-c", BUILD], cwd=ROOT, capture_output=True, text=True)
    if r.returncode != 0:
        print("BUILD FAILED")
        print((r.stdout + r.stderr)[-3000:])
